from pathlib import Path
from html import escape as e
from html.parser import HTMLParser
from urllib.parse import urljoin
import json, re, shutil

ROOT = Path(__file__).parent
AUDIT = ROOT.parent
DIST = ROOT / 'dist'
SITE = 'https://phoenix-foundation-irregularities.pfc.zone'
ORIGINAL = 'https://philipp-payments.pages.dev/'
LCD = 'https://terra-phoenix-api.highstakes.ch'
ARROW = '<svg class="arrow-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.5"/></svg>'
MARK = '<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M9 7v26h23M17 7v18h15M25 7v10h7" stroke="currentColor" stroke-width="2"/></svg>'
NAV = [('/', 'Review'), ('/voting/', '4853 & voting'), ('/stakeholders/', 'Stakeholders'), ('/treasury/', 'Treasury'), ('/governance/', 'Governance'), ('/evidence/', 'Evidence')]


def load(rel):
    return json.loads((AUDIT / rel).read_text())


def ext(url, text):
    return f'<a href="{e(url, quote=True)}">{e(text)}</a>'


def local(url, text):
    return f'<a href="{url}">{text}</a>'


def page(title, body, path='/', description='An evidence-based review of Phoenix governance, voting influence, treasury oversight and contract authority.'):
    nav = ''.join(f'<a href="{u}"' + (' aria-current="page"' if u == path else '') + f'>{t}</a>' for u, t in NAV)
    out = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Phoenix Governance Review</title><meta name="description" content="{e(description)}"><meta name="referrer" content="no-referrer"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{SITE + path}"><meta name="theme-color" content="#173d32"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><script defer src="/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/">{MARK}<span>Phoenix governance review<small>Public records · independent scrutiny</small></span></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-inner"><div><p>Process before personalities. Evidence before conclusions.</p><p>Evidence captured through 26 October 2026. Live votes and contract state can change.</p></div><nav aria-label="Footer"><a href="/evidence/">Method &amp; sources</a><a href="/record/">Preserved record</a><a href="/privacy/">Privacy</a></nav></div></footer></body></html>'''
    file = DIST / ('index.html' if path == '/' else path.strip('/') + '/index.html')
    file.parent.mkdir(parents=True, exist_ok=True)
    file.write_text(out)


def head(title, desc):
    return f'<div class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Governance review</a></p><h1>{title}</h1><p>{desc}</p></div></div>'


def nextlinks(left, right):
    return f'<nav class="next-reading" aria-label="Continue reading">{local(*left)}{local(*right)}</nav>'


def details(title, body, ident=''):
    idattr = f' id="{ident}"' if ident else ''
    return f'<details class="evidence-detail"{idattr}><summary>{title}</summary><div>{body}</div></details>'


def table(headers, rows, caption=''):
    cap = f'<caption>{caption}</caption>' if caption else ''
    th = ''.join(f'<th scope="col">{h}</th>' for h in headers)
    tr = ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in row) + '</tr>' for row in rows)
    return f'<div class="table-scroll"><table>{cap}<thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'


def source_list(items):
    return '<ul class="source-list">' + ''.join(f'<li>{ext(u, t)}</li>' for u, t in items) + '</ul>'


# Preserve the retrieved source corpus, but never restore its original narrative over the new review.
for p in (DIST / 'record').rglob('*.html'):
    if 'audit' in p.relative_to(DIST / 'record').parts:
        continue
    backup = ROOT / 'source-records' / 'original-pages' / p.relative_to(DIST / 'record')
    if not backup.exists():
        backup.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, backup)
    s = backup.read_text()
    def relocate(m):
        attr, q, value = m.groups()
        if value.startswith('/') and not value.startswith('//'):
            value = '/record' + value
        elif value.startswith(ORIGINAL):
            value = '/record/' + value[len(ORIGINAL):]
        return attr + '=' + q + value + q
    s = re.sub(r'(href|src|action)=([\'\"])(.*?)\2', relocate, s)
    banner = '<div style="padding:12px 20px;background:#e9f1ed;color:#203e35;font:16px/1.4 sans-serif;text-align:center">Preserved source presentation · <a href="/" style="color:#203e35">Return to the governance review</a></div>'
    p.write_text(re.sub(r'(<body[^>]*>)', r'\1' + banner, s, count=1))

